/* Account tokens stay in trusted extension session storage, never in run backups. */
(function(root){
'use strict';
const authKey='vault:account:session',receiptPrefix='billing:trial:';
function create({config=root.VaultCommercialConfig,session=root.chrome?.storage?.session,local=root.chrome?.storage?.local,fetch:request=root.fetch,clock=()=>Date.now()}={}){
 let refreshWork=null,sessionRevision=0;const enabled=config?.mode==='account';
 function origin(){const url=new URL(config?.apiOrigin||'https://unconfigured.invalid');if(!config?.apiOrigin)throw Error('Account service is not connected yet. Saved work is available.');if(url.protocol!=='https:'||url.pathname!=='/'||url.search||url.hash||url.username||url.password)throw Error('Invalid account service configuration.');return url.origin;}
 const read=async()=>(await session.get(authKey))[authKey]||null;
 const write=auth=>session.set({[authKey]:auth});
 async function raw(path,body,auth){const control=new AbortController(),timer=setTimeout(()=>control.abort(),12000);try{const response=await request(origin()+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json',...(auth?{Authorization:'Bearer '+auth.access_token}:{})},...(body===undefined?{}:{body:JSON.stringify(body)}),signal:control.signal,credentials:'omit',cache:'no-store'});const data=await response.json();if(!response.ok){const e=Error(data.error||'Account service is unavailable. Try again.');e.status=response.status;throw e;}return data;}catch(e){if(e.name==='AbortError')throw Error('Account service did not respond. No new test was started.');throw e;}finally{clearTimeout(timer);}}
 async function refresh(auth){if(!refreshWork){const revision=sessionRevision;refreshWork=raw('/auth/refresh',{refresh_token:auth.refresh_token}).then(async next=>{const current=await read();if(revision!==sessionRevision||current?.refresh_token!==auth.refresh_token)throw Error('Your account changed. Try this action again.');await write(next);return next;}).catch(async e=>{if(revision===sessionRevision&&(e.status===401||e.status===400))await write(null);throw e;}).finally(()=>refreshWork=null);}return refreshWork;}
 async function call(path,body){let auth=await read();if(!auth)throw Error('Sign in with your email to run tests or use Pro tools.');if(auth.expires_at*1000<=clock()+30000)auth=await refresh(auth);try{return await raw(path,body,auth);}catch(e){if(e.status!==401)throw e;auth=await refresh(auth);return raw(path,body,auth);}}
 async function status(){if(!enabled)return {enabled:false};if(!await read())return {enabled:true,signedIn:false,configured:!!config.apiOrigin};return {...await call('/account'),enabled:true,signedIn:true};}
 async function requireFeature(feature){const s=await status();if(!s.signedIn)throw Error('Sign in with your email to use this feature.');if(!s.pro)throw Error('Reusing saved settings and research tools are included in Pro at ₹899/month.');return s;}
 async function start(count){if(!Number.isInteger(count)||count<1||count>500)throw Error('Choose between 1 and 500 planned tests.');const s=await status();if(!s.signedIn)throw Error('Sign in with your email before starting tests.');if(!s.pro&&count>s.remaining)throw Error('This study needs '+count+' successful runs. You have '+s.remaining+' free runs available. Reduce the tests or upgrade to Pro.');return s;}
 async function reserve(runId){const s=await status();if(!s.signedIn)throw Error('Sign in before starting a test.');const existing=(await local.get(receiptPrefix+runId))[receiptPrefix+runId];if(existing&&existing.userId!==s.userId)throw Error('This trial belongs to another account. Sign in with the original email.');const receipt=await call('/runs/reserve',{runId});await local.set({[receiptPrefix+runId]:{runId,userId:s.userId,status:receipt.status}});return receipt;}
 async function settle(runId,outcome){const key=receiptPrefix+runId,r=(await local.get(key))[key];if(!r)return;const s=await status();if(!s.signedIn||s.userId!==r.userId)throw Error('Sign in with the account that started this test to finish its run count.');await call('/runs/settle',{runId,outcome});await local.set({[key]:{...r,status:outcome}});}
 async function recover(runId){if(typeof runId!=='string'||!/^[a-zA-Z0-9_-]{1,120}$/.test(runId))throw Error('Invalid run identity.');const state=await local.get(null);if(state['run:'+runId]||Object.entries(state).some(([k,e])=>k.startsWith('experiment:')&&e.trials?.some(t=>t.runId===runId)))throw Error('This trial is still in your library. Use Check saved result or Skip this trial in My studies.');return call('/runs/settle',{runId,outcome:'released'});}
 async function handle(m){if(!enabled)throw Error('Accounts are unavailable in this build.');switch(m.action){case 'status':return status();case 'pending':return call('/runs/pending');case 'recover-run':return recover(m.runId);case 'send-code':{const email=String(m.email||'').trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||email.length>254)throw Error('Enter a valid email address.');return raw('/auth/otp',{email});}case 'verify-code':{const auth=await raw('/auth/verify',{email:String(m.email||'').trim().toLowerCase(),token:String(m.token||'')});sessionRevision++;await write(auth);return status();}case 'sign-out':try{await call('/auth/logout',{});}finally{sessionRevision++;await write(null);}return {signedIn:false};case 'upgrade':return call('/billing/checkout',{});case 'cancel':return call('/billing/cancel',{});case 'refresh-billing':return call('/billing/refresh',{});case 'feature':return requireFeature(m.feature);case 'start':return start(m.count);default:throw Error('Unknown account command.');}}
 return {enabled,status,handle,start,reserve,settle,requireFeature};
}
const api={create};if(typeof module!=='undefined')module.exports=api;root.VaultAccounts=api;
})(globalThis);
